package pe.vichaval.gestionriego.reporte.service;
import java.io.ByteArrayOutputStream;import java.math.BigDecimal;import java.time.LocalDateTime;import java.time.format.DateTimeFormatter;import java.util.List;import com.lowagie.text.*;import com.lowagie.text.pdf.*;import org.springframework.stereotype.Service;import pe.vichaval.gestionriego.finanzas.entity.CuentaCobrar;import pe.vichaval.gestionriego.reporte.dto.ReporteFiltro;import pe.vichaval.gestionriego.tesoreria.entity.Pago;
@Service public class ReportePdfService {
 public byte[] pagos(List<Pago>d){return pagos(d,new ReporteFiltro(),"sistema");} public byte[] cuentas(List<CuentaCobrar>d){return cuentas(d,new ReporteFiltro(),"sistema");}
 public byte[] pagos(List<Pago>d,ReporteFiltro f,String u){BigDecimal t=d.stream().map(Pago::getMonto).reduce(BigDecimal.ZERO,BigDecimal::add);return crear("Reporte de pagos",f,u,d.size(),"Total: S/ "+t,new String[]{"Código","Fecha","Agricultor","Monto","Método","Estado"},d.stream().map(p->new String[]{p.getCodigo(),p.getFecha().toString(),p.getAgricultor().getNombres()+" "+p.getAgricultor().getApellidos(),"S/ "+p.getMonto(),p.getMetodo(),p.getEstado()}).toList());}
 public byte[] cuentas(List<CuentaCobrar>d,ReporteFiltro f,String u){BigDecimal t=d.stream().map(CuentaCobrar::getSaldoPendiente).reduce(BigDecimal.ZERO,BigDecimal::add);return crear("Reporte de cuentas por cobrar",f,u,d.size(),"Saldo pendiente: S/ "+t,new String[]{"Código","Agricultor","Vencimiento","Total","Saldo","Estado"},d.stream().map(c->new String[]{c.getCodigo(),c.getAgricultor().getNombres()+" "+c.getAgricultor().getApellidos(),c.getFechaVencimiento().toString(),"S/ "+c.getMontoTotal(),"S/ "+c.getSaldoPendiente(),c.getEstado()}).toList());}
 private byte[] crear(String titulo,ReporteFiltro f,String usuario,int cantidad,String total,String[]cols,List<String[]>filas){try(ByteArrayOutputStream out=new ByteArrayOutputStream()){Document doc=new Document(PageSize.A4.rotate(),28,28,28,28);PdfWriter.getInstance(doc,out);doc.open();doc.add(new Paragraph(titulo,FontFactory.getFont(FontFactory.HELVETICA_BOLD,16)));doc.add(new Paragraph("Vichayal Riego Web · Generado: "+LocalDateTime.now().format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"))));doc.add(new Paragraph("Usuario: "+usuario+" · Registros: "+cantidad+" · "+total));doc.add(new Paragraph("Filtros: desde="+v(f.getDesde())+", hasta="+v(f.getHasta())+", texto="+v(f.getQ())+", estado pago="+v(f.getEstadoPago())+", método="+v(f.getMetodo())+", estado cuenta="+v(f.getEstadoCuenta())+", vencimiento="+v(f.getVencimiento())));doc.add(Chunk.NEWLINE);PdfPTable table=new PdfPTable(cols.length);table.setWidthPercentage(100);for(String c:cols){PdfPCell cell=new PdfPCell(new Phrase(c,FontFactory.getFont(FontFactory.HELVETICA_BOLD,9)));cell.setBackgroundColor(new java.awt.Color(225,239,233));table.addCell(cell);}for(String[]fila:filas)for(String valor:fila)table.addCell(new Phrase(valor==null?"":valor,FontFactory.getFont(FontFactory.HELVETICA,8)));doc.add(table);doc.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException("No se pudo generar el PDF",e);}}
 private String v(Object x){return x==null||x.toString().isBlank()?"Todos":x.toString();}
}
